(function(){
'use strict';
if(window.__NORTH_PRIVATE_REPLY_INTERCEPT__)return;
window.__NORTH_PRIVATE_REPLY_INTERCEPT__='v1177-private-intercept-parity-1';

const KEY='north-role-intercept-last-v2';
const busy=new Set();
let memory={},activeTurn=null;
const baseChatAPI=chatAPI;
const baseAIReply=aiReply;
const baseOffAI=offAI;
const baseRenderContactSettings=renderContactSettings;
const baseOpenModal=openModal;
const baseCohabSettingsPanel=cohabSettingsPanel;

function lane(value){return value==='online'?'online':value==='cohab'?'cohab':'offline';}
function account(value){if(value!=null&&String(value).trim())return String(value);try{return String(actId()||'main');}catch(_){return'main';}}
function key(cid,channel,aid){const l=lane(channel),scope=l==='online'?account(aid):l;return [scope,String(cid||''),l].map(encodeURIComponent).join('|');}
function readAll(){try{const raw=sessionStorage.getItem(KEY),data=raw&&JSON.parse(raw);if(data&&typeof data==='object'&&!Array.isArray(data))memory=data;}catch(_){}return memory;}
function writeAll(rows){memory=rows;try{sessionStorage.setItem(KEY,JSON.stringify(rows));}catch(_){}return rows;}
function visibleText(value){let text=String(value==null?'':value);try{text=roleVisibleEnvelopeText(text);}catch(_){}return text.split(/\r?\n/).filter(line=>!/^[\[【][^\]】]{1,240}[\]】]$/.test(line.trim())).join('\n').replace(/[\u200b-\u200d\ufeff]/g,'').replace(/\s+/g,' ').trim();}
function clip(value){const chars=Array.from(String(value==null?'':value).trim());return{raw:chars.slice(0,12000).join(''),truncated:chars.length>12000};}
function turnStart(c,channel,aid,scene,before){return c&&c.id?{c,channel:lane(channel),account:lane(channel)==='online'?account(aid):lane(channel),scene:String(scene||''),before,candidates:[]}:null;}
function turnCandidate(turn,raw){const text=String(raw==null?'':raw).trim();if(turn&&text)turn.candidates.push({raw:text,stage:'模型候选 '+(turn.candidates.length+1)});return raw;}
function onlineRows(cid,aid){try{return msgsForAccount(cid,aid)||[];}catch(_){try{return msgs(cid)||[];}catch(__){return[];}}}
function sceneRows(cid,channel){if(channel==='cohab')return S.cohabitation&&S.cohabitation.homes&&S.cohabitation.homes[cid]&&S.cohabitation.homes[cid].msgs||[];return S.offline&&S.offline[cid]&&S.offline[cid].msgs||[];}
function rowText(row,channel){if(!row)return'';if(channel==='online'){if(row.role!=='assistant'||row.type==='sys')return'';return String(row.content||row.trans||'');}if(row.who!=='ta')return'';return String(row.text||'');}
function finish(turn){if(!turn||!turn.candidates.length)return false;const rows=turn.channel==='online'?onlineRows(turn.c.id,turn.account):sceneRows(turn.c.id,turn.channel),shown=rows.slice(turn.before).map(row=>rowText(row,turn.channel)).filter(Boolean),shownNorm=shown.map(visibleText).filter(Boolean),discarded=turn.candidates.filter((candidate,index)=>{const text=visibleText(candidate.raw);if(!text)return false;return !shownNorm.some(value=>value===text||value.includes(text)||text.includes(value))||index<turn.candidates.length-1;});if(!discarded.length)return false;const all=readAll(),items=discarded.map((item,index)=>{const c=clip(item.raw);return{index:index+1,stage:item.stage,reason:'这份模型候选没有原样展示',action:shown.length?'被后续候选或本机处理替代':'整轮回复被隐藏或没有留下可显示内容',raw:c.raw,truncated:c.truncated};}),first=items[0];all[key(turn.c.id,turn.channel,turn.account)]={version:2,roleId:String(turn.c.id),roleName:String(turn.c.remark||turn.c.name||'角色').slice(0,80),channel:turn.channel,account:turn.account,at:Date.now(),scene:turn.scene,items,reason:first.reason,action:first.action,raw:first.raw,truncated:first.truncated};Object.keys(all).sort((a,b)=>(+all[b].at||0)-(+all[a].at||0)).slice(60).forEach(k=>delete all[k]);writeAll(all);return true;}
function read(c,channel,aid){if(!c||!c.id)return null;const l=lane(channel),row=readAll()[key(c.id,l,aid)];return row&&row.roleId===String(c.id)&&row.channel===l?row:null;}

chatAPI=async function(messages,opt){const out=await baseChatAPI.apply(this,arguments);if(!(opt&&opt.theaterActor))turnCandidate(activeTurn,out);return out;};
aiReply=async function(id,note,replyToken,replyAccount,replyIntent){const c=getC(id),aid=replyAccount||account(),rows=onlineRows(id,aid),parent=activeTurn,turn=turnStart(c,'online',aid,'线上微信',rows.length);activeTurn=turn;try{return await baseAIReply.apply(this,arguments);}finally{activeTurn=parent;finish(turn);}};
offAI=async function(note){if(!_off)return baseOffAI.apply(this,arguments);const id=_off.id,c=getC(id),channel=_off.mode==='cohab'?'cohab':'offline',rows=sceneRows(id,channel),parent=activeTurn,turn=turnStart(c,channel,null,channel==='cohab'?'共同生活':'单次约会',rows.length);activeTurn=turn;try{return await baseOffAI.apply(this,arguments);}finally{activeTurn=parent;finish(turn);}};

function open(cid,channel){const c=getC(cid);if(!c)return;const l=lane(channel),row=read(c,l),where=l==='online'?'线上微信':l==='cohab'?'共同生活':'单次约会';if(!row){baseOpenModal(`<h3>上一轮拦截内容</h3><div class="hint">${where}暂时没有可查看的拦截正文。这里会记录模型已经返回、但没有原样展示的回复候选；网络失败、空响应和正常显示的回复不算拦截。</div><button class="btn g" style="margin-top:12px" onclick="closeModal()">关闭</button>`);return;}const items=Array.isArray(row.items)&&row.items.length?row.items:[row],body=items.map((item,index)=>{const cut=item.truncated?'\n\n（原文超过 12000 字，仅保留前 12000 字。）':'';return `<section style="margin-top:14px"><div class="section"><div class="it"><span>候选</span><span class="v">${esc((index+1)+' / '+items.length+' · '+(item.stage||'模型候选'))}</span></div><div class="it"><span>未展示原因</span><span class="v">${esc(item.reason||row.reason||'未原样展示')}</span></div><div class="it"><span>处理方式</span><span class="v">${esc(item.action||row.action||'被替换或隐藏')}</span></div></div><pre style="margin:7px 0 0;max-height:34vh;overflow:auto;white-space:pre-wrap;word-break:break-word;border:1px solid #34343a;border-radius:12px;background:#121214;color:#ddd;padding:12px;font:13px/1.65 ui-monospace,SFMono-Regular,Menlo,monospace">${esc(String(item.raw||'')+cut)}</pre></section>`;}).join(''),release=row.releasedAt?'<button class="btn p" disabled>已释放到聊天</button>':`<button class="btn p" data-cid="${esc(String(cid))}" data-channel="${l}" onclick="roleInterceptDiagnosticRelease(this.dataset.cid,this.dataset.channel)">释放全部到聊天</button>`;baseOpenModal(`<h3>上一轮拦截内容</h3><div class="hint">记录只存在当前本机运行会话；除非主动释放，否则不会写进聊天、角色记忆或云同步。</div><div class="section" style="margin-top:12px"><div class="it"><span>位置</span><span class="v">${esc(where)}</span></div><div class="it"><span>角色</span><span class="v">${esc(row.roleName)}</span></div><div class="it"><span>时间</span><span class="v">${esc(fmtDT(row.at))}</span></div><div class="it"><span>候选数量</span><span class="v">${items.length}</span></div></div>${body}<div class="btns" style="margin-top:12px"><button class="btn g" onclick="closeModal()">关闭</button>${release}</div>`);}
window.roleInterceptDiagnosticOpen=open;

async function release(cid,channel){const c=getC(cid);if(!c)return false;const l=lane(channel),aid=l==='online'?account():undefined,row=read(c,l,aid);if(!row||row.releasedAt)return toast(row&&row.releasedAt?'这轮内容已经释放过了':'这轮拦截记录已经不存在'),false;const items=(Array.isArray(row.items)?row.items:[row]).map(item=>String(item&&item.raw||'').trim()).filter(Boolean),releaseKey=key(c.id,l,aid);if(!items.length||busy.has(releaseKey))return false;if(!await uiConfirm('把这一轮全部 '+items.length+' 份模型候选原样释放到'+(l==='online'?'微信':l==='cohab'?'共同生活':'单次约会')+'聊天？\n\n内容可能重复或互相矛盾；只写入原文，不重新执行其中的功能标签。'))return false;busy.add(releaseKey);let list,before=0,beforeSeq=0;try{if(l==='online')list=onlineRows(c.id,aid);else list=sceneRows(c.id,l);before=list.length;if(l==='cohab'){const d=S.cohabitation.homes[c.id];beforeSeq=+d.msgSeq||0;items.forEach((text,index)=>{d.msgSeq=(+d.msgSeq||0)+1;list.push({id:uid(),time:Date.now()+index,cohabSeq:d.msgSeq,who:'ta',text,_interceptReleased:true});});}else if(l==='offline')items.forEach((text,index)=>list.push({id:uid(),time:Date.now()+index,who:'ta',text,_interceptReleased:true}));else items.forEach((text,index)=>list.push({id:uid(),time:Date.now()+index,role:'assistant',type:'text',content:text,_interceptReleased:true}));if(await saveNowAsync()===false)throw new Error('聊天保存失败，已撤回本次释放');const all=readAll(),stored=all[releaseKey];if(stored&&stored.at===row.at){stored.releasedAt=Date.now();stored.releasedCount=items.length;writeAll(all);}closeModal();if(l==='online')openChat(c.id);else if(typeof offRender==='function')offRender();else render();toast('已释放 '+items.length+' 份拦截候选');return true;}catch(e){if(list&&list.length>before)list.splice(before);if(l==='cohab'&&S.cohabitation&&S.cohabitation.homes&&S.cohabitation.homes[c.id])S.cohabitation.homes[c.id].msgSeq=beforeSeq;try{save(0);}catch(_){}toast(String(e&&e.message||e||'释放失败'));return false;}finally{busy.delete(releaseKey);}}
window.roleInterceptDiagnosticRelease=release;

renderContactSettings=function(id){const html=baseRenderContactSettings.apply(this,arguments);if(!html||html.includes("roleInterceptDiagnosticOpen('"+id+"','online')"))return html;return html.replace('<div class="wx-info-label">角色设置</div>',`<div class="wx-info-group"><button onclick="roleInterceptDiagnosticOpen('${id}','online')"><span>查看上一轮拦截内容</span><em>仅本机诊断　›</em></button></div><div class="wx-info-label">角色设置</div>`);};
openModal=function(html){if(typeof html==='string'&&html.includes('<h3>约会设定</h3>')&&!html.includes("roleInterceptDiagnosticOpen('") )html=html.replace('<div class="btns">',`<button class="btn g" style="margin-bottom:10px" onclick="closeModal();roleInterceptDiagnosticOpen('${_off&&_off.id||''}','offline')">查看上一轮拦截内容</button><div class="btns">`);return baseOpenModal.call(this,html);};
cohabSettingsPanel=function(id,o){const html=baseCohabSettingsPanel.apply(this,arguments);if(!html||html.includes("roleInterceptDiagnosticOpen('"+id+"','cohab')"))return html;return html.replace('</div></details>',`<button type="button" class="cohab-memory-open" onclick="roleInterceptDiagnosticOpen('${id}','cohab')"><span>查看上一轮拦截内容</span><small>仅本机诊断 ›</small></button></div></details>`);};
})();
